//! RULES.md R-TRACE: every test names the requirements it verifies, in a
//! `/// Verifies:` doc paragraph above it that starts with an allowed tag.
//!
//! The scan reads source text line by line. It does not expand macros, so a
//! test generated by a macro is not traced; the project has none.

use std::path::Path;

use crate::error::{Error, Result};
use crate::files;

const VERIFIES: &str = "/// Verifies:";
const DOC: &str = "///";
const COMMENT: &str = "//";
const TEST_ATTRIBUTE: &str = "#[test]";
const ATTRIBUTE: &str = "#[";
/// Shown for a test with no requirements.
const MISSING: &str = "MISSING";
/// A `Verifies:` paragraph starts with one of these (RULES.md R-TRACE-1).
const ALLOWED_TAGS: [&str; 4] = ["[X3.135-1986 §", "[EXTENSION]", "[DESIGN]", "[TOOL] R-"];

/// One test and the requirements it names, if any.
#[derive(Debug, PartialEq)]
pub struct Entry {
    pub test: String,
    pub verifies: Option<String>,
}

/// Prints `test<TAB>requirements` for the tests that mention `filter`, then
/// fails if any test is not traced.
pub fn print(root: &Path, filter: &str) -> Result<()> {
    let entries = collect(root)?;
    for entry in &entries {
        let verifies = entry.verifies.as_deref().unwrap_or(MISSING);
        if mentions(&entry.test, filter) || mentions(verifies, filter) {
            println!("{}\t{verifies}", entry.test);
        }
    }
    untraced(&entries)
}

/// Fails if any test is not traced.
pub fn check(root: &Path) -> Result<()> {
    let entries = collect(root)?;
    untraced(&entries)?;
    println!("traceability: ok ({} tests)", entries.len());
    Ok(())
}

fn collect(root: &Path) -> Result<Vec<Entry>> {
    let mut entries = Vec::new();
    for file in files::rust_files(root)? {
        entries.extend(parse(&file, &files::read(root, &file)?));
    }
    Ok(entries)
}

/// Whether a `Verifies:` paragraph traces its test: it starts with an allowed tag.
fn traced(verifies: Option<&str>) -> bool {
    verifies.is_some_and(|v| ALLOWED_TAGS.iter().any(|tag| v.starts_with(tag)))
}

fn untraced(entries: &[Entry]) -> Result<()> {
    let untraced: Vec<&str> = entries.iter().filter(|e| !traced(e.verifies.as_deref())).map(|e| e.test.as_str()).collect();
    if untraced.is_empty() {
        Ok(())
    } else {
        let tags = ALLOWED_TAGS.join(", ");
        Err(Error::new(format!("R-TRACE-1: tests without a `{VERIFIES}` paragraph starting with one of {tags}:\n{}", untraced.join("\n"))))
    }
}

/// Whether `text` mentions `filter` as a whole token: "§8.1" is mentioned by
/// "§8.1 GR2" and "§8.1," but not by "§8.10" or "§8.1.2".
fn mentions(text: &str, filter: &str) -> bool {
    filter.is_empty()
        || text.match_indices(filter).any(|(at, _)| {
            let rest = text.get(at..).and_then(|s| s.strip_prefix(filter)).unwrap_or_default();
            !continues_number(rest)
        })
}

/// Whether `rest` continues a number that ends just before it: a digit, or a
/// `.` followed by a digit.
fn continues_number(rest: &str) -> bool {
    let mut chars = rest.chars();
    let (first, second) = (chars.next(), chars.next());
    first.is_some_and(|c| c.is_ascii_digit()) || (first == Some('.') && second.is_some_and(|c| c.is_ascii_digit()))
}

/// The tests in one file. A `Verifies:` paragraph runs until a blank doc line
/// or the end of the doc comment; it belongs to the test that follows it.
pub fn parse(file: &str, text: &str) -> Vec<Entry> {
    let mut scan = Scan::default();
    text.lines()
        .filter_map(|line| scan.line(line.trim_start()))
        .map(|(name, verifies)| Entry { test: format!("{file}::{name}"), verifies })
        .collect()
}

/// What the scan of one file knows before the current line.
#[derive(Default)]
struct Scan {
    verifies: Option<String>,
    in_paragraph: bool,
    is_test: bool,
    /// `[`s of an attribute still open at the end of the previous line.
    open_brackets: usize,
}

impl Scan {
    /// Reads one line; returns the name and requirements of a test it declares.
    fn line(&mut self, line: &str) -> Option<(String, Option<String>)> {
        if self.open_brackets > 0 {
            self.open_brackets = bracket_depth(self.open_brackets, line); // an attribute continues
        } else if let Some(rest) = line.strip_prefix(VERIFIES) {
            self.verifies = Some(rest.trim().to_owned());
            self.in_paragraph = true;
        } else if let Some(rest) = line.strip_prefix(DOC) {
            self.in_paragraph = continue_paragraph(&mut self.verifies, self.in_paragraph, rest.trim());
        } else if line.is_empty() || line.starts_with(COMMENT) {
            // Blank lines and comments do not detach a doc comment from its item.
        } else if let Some(rest) = line.strip_prefix(TEST_ATTRIBUTE) {
            self.is_test = true;
            let rest = rest.trim_start();
            if !rest.is_empty() {
                return self.item(rest); // `#[test] fn t()` on one line
            }
        } else if line.starts_with(ATTRIBUTE) {
            self.open_brackets = bracket_depth(0, line);
        } else {
            return self.item(line);
        }
        None
    }

    /// A line of code ends what the doc comment and attributes applied to; it
    /// completes a test when it declares the function after `#[test]`.
    fn item(&mut self, line: &str) -> Option<(String, Option<String>)> {
        let test = if self.is_test { fn_name(line).map(|name| (name.to_owned(), self.verifies.take())) } else { None };
        *self = Scan::default();
        test
    }
}

/// The count of open `[` after `line`, starting from `depth`.
fn bracket_depth(depth: usize, line: &str) -> usize {
    line.chars().fold(depth, |d, c| match c {
        '[' => d.saturating_add(1),
        ']' => d.saturating_sub(1),
        _ => d,
    })
}

/// Appends a doc line to an open `Verifies:` paragraph; a blank line closes it.
/// Returns whether the paragraph is still open.
fn continue_paragraph(verifies: &mut Option<String>, open: bool, text: &str) -> bool {
    let Some(paragraph) = verifies.as_mut() else { return false };
    if !open || text.is_empty() {
        return false;
    }
    paragraph.push(' ');
    paragraph.push_str(text);
    true
}

/// What starts a function's name in its declaration.
const FN_KEYWORD: &str = "fn ";

/// The function name in a line like `fn name(` or `pub fn name(`.
fn fn_name(line: &str) -> Option<&str> {
    let (_, after) = line.split_once(FN_KEYWORD)?;
    after.split_once('(').map(|(name, _)| name)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(test: &str, verifies: Option<&str>) -> Entry {
        Entry { test: test.to_owned(), verifies: verifies.map(str::to_owned) }
    }

    /// Verifies: [TOOL] R-TRACE-1 a multi-line `Verifies:` paragraph is read whole,
    /// and stops at a blank doc line.
    #[test]
    fn paragraph_continues_until_blank_line() {
        let text = "/// Verifies: [A]\n/// and [B].\n///\n/// Notes.\n#[test]\nfn t() {}\n";
        assert_eq!(parse("f.rs", text), vec![entry("f.rs::t", Some("[A] and [B]."))]);
    }

    /// Verifies: [TOOL] R-TRACE-1 a test without `Verifies:` is found, and a
    /// `Verifies:` line does not carry over to the next function.
    #[test]
    fn missing_verifies_is_found() {
        let text = "/// Verifies: [A]\nfn helper() {}\n\n#[test]\nfn t() {}\n";
        assert_eq!(parse("f.rs", text), vec![entry("f.rs::t", None)]);
    }

    /// Verifies: [TOOL] R-TRACE-1 functions that are not tests are not listed.
    #[test]
    fn non_tests_are_ignored() {
        assert_eq!(parse("f.rs", "/// Verifies: [A]\n#[inline]\nfn f() {}\n"), vec![]);
    }

    /// Verifies: [TOOL] R-TRACE-1 tests are found after a multi-line attribute,
    /// on one line with `#[test]`, and across blank and comment lines.
    #[test]
    fn tests_are_found_in_every_layout() {
        let wrapped = "/// Verifies: [A]\n#[test]\n#[should_panic(\n    expected = \"x\"\n)]\nfn wrapped() {}\n";
        assert_eq!(parse("f.rs", wrapped), vec![entry("f.rs::wrapped", Some("[A]"))]);
        assert_eq!(parse("f.rs", "/// Verifies: [A]\n#[test] fn one_line() {}\n"), vec![entry("f.rs::one_line", Some("[A]"))]);
        let spaced = "/// Verifies: [A]\n\n// a note\n#[test]\nfn spaced() {}\n";
        assert_eq!(parse("f.rs", spaced), vec![entry("f.rs::spaced", Some("[A]"))]);
    }

    /// Verifies: [TOOL] R-TRACE-1 only a paragraph starting with an allowed tag
    /// traces its test; an empty or free-text one does not.
    #[test]
    fn only_allowed_tags_trace() {
        assert!(traced(Some("[X3.135-1986 §8.6 GR2] fetch")));
        assert!(traced(Some("[TOOL] R-SIZE-2 limits")));
        assert!(!traced(Some("")));
        assert!(!traced(Some("checks things")));
        assert!(!traced(None));
    }

    /// Verifies: [TOOL] R-TRACE-2 a clause filter matches the clause, not a longer
    /// number that starts with it.
    ///
    /// Decision `digit || ('.' && digit)`. MC/DC: "§8.1 " (F, F F) matches;
    /// "§8.10" (T) does not; "§8.1.2" (F, T T) does not; "§8.1." (F, T F) matches.
    #[test]
    fn filters_match_whole_clauses() {
        assert!(mentions("[X3.135-1986 §8.1 GR1]", "§8.1"));
        assert!(!mentions("[X3.135-1986 §8.10 GR2]", "§8.1"));
        assert!(!mentions("[X3.135-1986 §8.1.2]", "§8.1"));
        assert!(mentions("ends with §8.1.", "§8.1"));
        assert!(mentions("anything", ""));
    }
}
